r=Path(__file__).resolve().parents[3];d=r/'data/venue_refs/floor_plans_v3/dual_unit_residential_floor_03';out=d/'wc117_support_clearance_trial';folders=[d/'wc109_trap_pilot_v8',out];receipts=[json.loads((x/'candidate_cpu/candidate/render_receipt.json').read_text()) for x in folders];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
